-- Schema do Guia de Negócios da Cidade. Execute este arquivo somente se recriar o banco.
create extension if not exists pgcrypto;
create table if not exists public.cidades(id uuid primary key default gen_random_uuid(),nome text not null,estado char(2) not null,slug text not null unique,criado_em timestamptz not null default now());
create table if not exists public.categorias(id uuid primary key default gen_random_uuid(),nome text not null,slug text not null unique,criado_em timestamptz not null default now());
create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade,criado_em timestamptz not null default now());
create table if not exists public.negocios(id uuid primary key default gen_random_uuid(),cidade_id uuid not null references public.cidades(id),categoria_id uuid not null references public.categorias(id),nome text not null check(char_length(trim(nome)) between 2 and 120),slug text not null unique check(slug ~ '^[a-z0-9-]+$'),descricao text,servicos jsonb not null default '[]'::jsonb,bairro text,endereco text,whatsapp text not null check(whatsapp ~ '^[0-9]{10,15}$'),telefone text check(telefone is null or telefone ~ '^[0-9]{10,15}$'),instagram text,horario text,logo_url text,fotos_urls jsonb not null default '[]'::jsonb,destaque boolean not null default false,ativo boolean not null default true,criado_em timestamptz not null default now());
create table if not exists public.cliques(id bigint generated by default as identity primary key,negocio_id uuid not null references public.negocios(id) on delete cascade,tipo text not null check(tipo in('whatsapp','ligacao')),criado_em timestamptz not null default now());
insert into public.cidades(nome,estado,slug) values('Itaiá','BA','itaia') on conflict(slug) do nothing;
insert into public.categorias(nome,slug) values('Eletricista','eletricista'),('Salão de beleza','salao-de-beleza'),('Mercado','mercado'),('Diarista','diarista'),('Restaurante','restaurante'),('Barbearia','barbearia'),('Oficina','oficina'),('Outros','outros') on conflict(slug) do nothing;
alter table public.cidades enable row level security;alter table public.categorias enable row level security;alter table public.admins enable row level security;alter table public.negocios enable row level security;alter table public.cliques enable row level security;
create policy "public read cities" on public.cidades for select to anon,authenticated using(true);
create policy "public read categories" on public.categorias for select to anon,authenticated using(true);
create policy "admin read own row" on public.admins for select to authenticated using((select auth.uid())=user_id);
create policy "public read active businesses" on public.negocios for select to anon,authenticated using(ativo=true);
create policy "admin read all businesses" on public.negocios for select to authenticated using((current_setting('request.jwt.claims',true)::jsonb->'app_metadata'->>'is_admin')='true');
create policy "admin insert businesses" on public.negocios for insert to authenticated with check((current_setting('request.jwt.claims',true)::jsonb->'app_metadata'->>'is_admin')='true');
create policy "admin update businesses" on public.negocios for update to authenticated using((current_setting('request.jwt.claims',true)::jsonb->'app_metadata'->>'is_admin')='true') with check((current_setting('request.jwt.claims',true)::jsonb->'app_metadata'->>'is_admin')='true');
create policy "admin delete businesses" on public.negocios for delete to authenticated using((current_setting('request.jwt.claims',true)::jsonb->'app_metadata'->>'is_admin')='true');
create policy "public insert clicks" on public.cliques for insert to anon,authenticated with check(tipo in('whatsapp','ligacao') and exists(select 1 from public.negocios n where n.id=negocio_id and n.ativo=true));
create policy "admin read clicks" on public.cliques for select to authenticated using((current_setting('request.jwt.claims',true)::jsonb->'app_metadata'->>'is_admin')='true');